from pydantic import AliasGenerator, BaseModel, ConfigDict

def test_distinct_generated_aliases_round_trip():
    class Message(BaseModel):
        model_config = ConfigDict(alias_generator=AliasGenerator(
            alias=lambda name: 'common_' + name,
            validation_alias=lambda name: 'in_' + name,
            serialization_alias=lambda name: 'out_' + name,
        ))
        value: int

    message = Message.model_validate({'in_value': 7})
    assert message.model_dump(by_alias=True) == {'out_value': 7}

from pydantic import BaseModel, Field
from pydantic.fields import FieldInfo

def test_trusted_construction_passes_previous_field_values():
    class Invoice(BaseModel):
        subtotal: int
        total: int = Field(default_factory=lambda data: data['subtotal'] + 5)

    assert Invoice.model_construct(subtotal=20).total == 25

def test_explicit_default_resolution_passes_supplied_values():
    field = FieldInfo(default_factory=lambda data: data['subtotal'] + 5)
    assert field.get_default(call_default_factory=True, validated_data={'subtotal': 20}) == 25
